// Builds ONE SQL file that brings an EMPTY Supabase project up to the same schema as
// production, for stress testing. It never connects to anything — it only reads
// ../../supabase/*.sql and writes out/staging-schema.sql.
//
//   node tests/stress/build-schema-bundle.mjs
//
// The order below is copied from scripts/db-migrations.test.mjs, which is the only place
// the real run order is proven (CLAUDE.md warns the table in the docs is NOT in run order).
// Run the result in the STAGING project's SQL editor — never production.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { fileURLToPath } from "node:url";

const SQL = new URL("../../supabase/", import.meta.url);
const OUT = new URL("./out/", import.meta.url);

// Exactly the order scripts/db-migrations.test.mjs applies them in.
const FILES = [
  "schema-v2.sql",
  "migration-2026-09-project-adviser.sql",
  "migration-2026-09-security-hardening.sql",
  "migration-2026-09b-pin-and-judge-auth.sql",
  "migration-2026-10-project-details.sql",
  "migration-2026-10b-private-members-and-registration.sql",
  "migration-2026-10c-secure-school-signup.sql",
  "migration-2026-10d-judge-revise-validation.sql",
  "migration-2026-10e-categories-and-department-codes.sql",
  "migration-2026-10f-scoring-modes.sql",
  "migration-2026-10g-school-judge-numbers.sql",
  "migration-2026-10h-shared-judges.sql",
  "migration-2026-10i-judge-max.sql",
  "migration-2026-10j-department-rubrics.sql",
  "migration-2026-10k-judge-roster-and-panels.sql",
  "migration-2026-10l-school-branding.sql",
  "migration-2026-10m-ratelimit-regnum-project-moves.sql",
  "migration-2026-10n-unique-project-numbers.sql",
  "migration-2026-10o-score-feedback.sql",
  "migration-2026-10p-judging-schedule.sql",
  "migration-2026-11a-judge-write-integrity.sql",
  "migration-2026-11b-invite-lockout-per-device.sql",
];

const WARN = `-- ⚠️  Run this ONLY in the empty STAGING Supabase project.
--     NEVER in the production project (evrupqnhgrfltfhafeyj) — it already has this schema
--     and 63 real projects with student names.`;

// One entry per source file, kept whole: a part boundary may never fall inside a file,
// because several migrations contain "-- ═══" banner lines INSIDE $$ function bodies.
const pieces = FILES.map((f) => ({
  name: f,
  text: `\n-- ════════════════════════════════════════════════════════════════════════════\n-- ${f}\n-- ════════════════════════════════════════════════════════════════════════════\n${readFileSync(new URL(f, SQL), "utf8")}\n`,
}));

mkdirSync(fileURLToPath(OUT), { recursive: true });

// 1) The whole thing, for one paste.
const head = `-- ============================================================================
-- STAGING schema bundle for stress testing — generated by tests/stress/build-schema-bundle.mjs
-- ${FILES.length} files, in the order scripts/db-migrations.test.mjs proves.
--
${WARN}
-- ============================================================================

`;
const all = head + pieces.map((p) => p.text).join("");
writeFileSync(new URL("staging-schema.sql", OUT), all);
console.log(`staging-schema.sql — ${FILES.length} files, ${all.length.toLocaleString()} chars`);

// 2) Parts of ≤ MAX chars, split only between whole files, for editors that balk at one big paste.
const MAX = 70000;
const parts = [];
for (const p of pieces) {
  if (!parts.length || parts.at(-1).size + p.text.length > MAX) parts.push({ items: [], size: 0 });
  parts.at(-1).items.push(p);
  parts.at(-1).size += p.text.length;
}
parts.forEach((part, i) => {
  const banner = `-- STAGING schema bundle — PART ${i + 1} of ${parts.length}. Run the parts IN ORDER.\n`
    + `-- Files in this part:\n${part.items.map((x) => `--   ${x.name}`).join("\n")}\n--\n${WARN}\n\n`;
  writeFileSync(new URL(`staging-schema-part${i + 1}.sql`, OUT), banner + part.items.map((x) => x.text).join(""));
  console.log(`  part${i + 1}: ${part.size.toLocaleString().padStart(8)} chars — ${part.items.length} file(s): ${part.items[0].name} … ${part.items.at(-1).name}`);
});
